def start_ingest(spark: SparkSession, landing: str, table: str, schema_path: str, checkpoint: str) -> StreamingQuery:
    """Load new files from landing into table. checkpoint must be unique to this stream."""
    raw = spark.readStream.format("cloudFiles").option("cloudFiles.format", "csv").option("cloudFiles.schemaLocation", schema_path).load(landing)
    return raw.writeStream.option("checkpointLocation", checkpoint).trigger(availableNow=True).toTable(table)
